import { defineStore } from "pinia";

export const useCrosshairStore = defineStore("crosshair", {
  state: () => {
    return {
      profiles: [
        {
          id: 1,
          label: "Profile 1",
          layers: [
            {
              width: 1,
            },
          ],
        },
      ],
      selectedProfile: 1,
    };
  },
  actions: {
    getSelectedProfile() {
      return this.profiles.find(
        (profile) => profile.id === this.selectedProfile
      );
    },
    getSelectedLayers() {
      return this.getSelectedProfile().layers;
    },
    updateLayerKey(index, key, value) {
      console.log(this.getSelectedLayers()[0]);
      //this.getSelectedLayers()[index][key] = value;
    },
    getLayerByIndex(index) {
      return this.getSelectedLayers()[index];
    },
  },
});
