<template>
  <div :class="['h-full min-h-full w-full min-w-full', tabClass]" v-show="title === selectedTitle">
    <slot />
  </div>
</template>

<script>
import { inject } from "vue";

export default {
  name: "gm-tab",
  props: ["title", "tabClass"],
  setup() {
    const selectedTitle = inject("selectedTitle");
    const tabTitles = inject("tabTitles");

    return {
      selectedTitle,
      tabTitles,
    };
  },
};
</script>

<style scoped lang="scss"></style>
