<template>
  <TabsWrapper wrap="settingsTabsWrap" ref="selector" :key="renderKey">
    <Tab
      v-for="category in devMode ? devCategories : categories"
      :key="category"
      :title="category.name"
    >
      <Settings :options="category.settings" :ref="category.name" />
    </Tab>
    <Tab title="Crosshair">
      <!-- <crosshair-box :devMode="devMode" ref="crosshair" /> -->
      <CrosshairTab :devMode="devMode" />
    </Tab>
  </TabsWrapper>
</template>

<script>
import TabsWrapper from "../../../../components/TabsWrapper.vue";
import Tab from "../../../../components/Tab.vue";
import Settings from "./Settings";
import CrosshairTab from "./Crosshair/CrosshairTab.vue";
//import CrosshairBox from "../../../components/custom/Crosshair/CrosshairBox.vue";
export default {
  name: "SettingsTab",
  props: ["devMode"],
  components: { Settings, Tab, TabsWrapper, CrosshairTab },
  data() {
    return {
      categories: [{ name: "default" }],
      devCategories: Array(this.getRndInt(2, 10))
        .fill()
        .map(() => ({
          name: this.makeid(5),
          settings: Array(this.getRndInt(5, 20))
            .fill()
            .map(() => {
              switch (this.getRndInt(1, 5)) {
                case 1:
                  return {
                    id: this.getRndInt(1, 2000),
                    type: 1,
                    name: this.makeid(5),
                    label: this.makeid(5),
                    description: this.makeid(20),
                  };
                case 2:
                  return {
                    id: this.getRndInt(1, 2000),
                    type: 2,
                    name: this.makeid(5),
                    label: this.makeid(5),
                    description: this.makeid(20),
                    options: Array(this.getRndInt(3, 10))
                      .fill()
                      .map(() => ({
                        name: this.makeid(5),
                        value: this.makeid(5),
                      })),
                  };
                case 3:
                  return {
                    id: this.getRndInt(1, 2000),
                    type: 3,
                    name: this.makeid(5),
                    label: this.makeid(5),
                    description: this.makeid(20),
                  };
                case 4:
                  return {
                    id: this.getRndInt(1, 2000),
                    type: 4,
                    name: this.makeid(5),
                    label: this.makeid(5),
                    description: this.makeid(20),
                    options: Array(this.getRndInt(3, 10))
                      .fill()
                      .map(() => ({
                        name: this.makeid(5),
                        value: this.makeid(5),
                      })),
                  };
              }
            }),
        })),
      renderKey: 0,
    };
  },
  watch: {
    categories: {
      handler() {
        this.renderKey++;
      },
      deep: true,
    },
    devCategories: {
      handler() {
        this.renderKey++;
      },
      deep: true,
    },
  },
  mounted() {
    //wait 5 sec
  },
  methods: {
    makeid(length) {
      var result = "";
      var characters =
        "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
      var charactersLength = characters.length;
      for (var i = 0; i < length; i++) {
        result += characters.charAt(
          Math.floor(Math.random() * charactersLength)
        );
      }
      return result;
    },
    getRndInt(min, max) {
      return Math.floor(Math.random() * (max - min)) + min;
    },
  },
};
</script>

<style src="@vueform/toggle/themes/default.css"></style>

<style lang="scss">
:root {
  --toggle-bg-on: rgb(91, 145, 254);
  --toggle-border-on: rgb(91, 145, 254);

  --toggle-bg-off: transparent;
  --toggle-border-off: rgb(78, 78, 78);
  --toggle-ring-width: 0px;
}

.settingsTabsWrap {
  .headers {
    display: flex;
    width: 100%;
    justify-content: center;
    align-items: center;
    color: #ced6e2a6;

    position: absolute;
    top: -50px;
    z-index: 150;

    .selected {
      color: $blue !important;
      background: rgba($blue, 0.1);
    }

    .header {
      transition: background 0.3s;
      margin: 0px 10px 0 10px;
      display: grid;
      justify-content: center;
      align-items: center;
      cursor: pointer;
      padding: 10px;
      border-radius: 15px;
      font-size: 17px;
      font-weight: 500;
    }
  }
}
</style>

<style scoped lang="scss">
* {
  overflow: visible !important;
}
</style>
