<template>
  <Transition @leave="stopSound" name="slide-side-right">
    <AuthPanel v-show="authPanel" ref="panel" />
  </Transition>
</template>

<script>
import AuthPanel from "./AuthPanel.vue";

export default {
  name: "Auth",
  components: { AuthPanel },
  data() {
    return {
      authPanel: false,
    };
  },
  methods: {
    startLoading(sec = 5) {
      global.gm.$refs.loadingScreen.show(sec * 1000);
      setTimeout(() => {
        setTimeout(() => {
          this.authPanel = true;
          this.$refs.panel.play();
        }, 1000);
      }, sec * 1000);
    },
    stopSound() {
      this.$refs.panel.stop();
    },
  },
};
</script>

<style scoped lang="scss"></style>
