<template>
  <div>
    <label for="color">Color</label>
    <ColorPicker
      v-model="newSettings.color"
      @input="$emit('updateLayer', this.newSettings)"
    />
  </div>
  <div>
    <label>Width2: {{ newSettings.width }}</label>
    <vue-slider
      :tooltip="'none'"
      :v-model="selectedLayer.width"
      @change="updateLayerKey2(0, 'width', this.newSettings.width)"
      :interval="0.1"
      :min="0.1"
      :max="200"
    />
  </div>
  <div v-if="true">
    <div>
      <label>Separated Size</label>
      <Toggle v-model="newSettings.size.separated" />
    </div>
    <div v-if="!newSettings.size.separated">
      <label>Size: {{ newSettings.size.y }}</label>
      <vue-slider
        :tooltip="'none'"
        v-model="newSettings.size.y"
        @change="$emit('updateLayer', this.newSettings)"
        :interval="0.1"
        :min="0.1"
        :max="200"
      />
    </div>
    <div v-else>
      <div>
        <label>Vertical Size: {{ newSettings.size.y }}</label>
        <vue-slider
          :tooltip="'none'"
          v-model="newSettings.size.y"
          @change="$emit('updateLayer', this.newSettings)"
          :interval="0.1"
          :min="0.1"
          :max="200"
        />
      </div>
      <div>
        <label>Horizontal Size: {{ newSettings.size.x }}</label>
        <vue-slider
          :tooltip="'none'"
          v-model="newSettings.size.x"
          @change="$emit('updateLayer', this.newSettings)"
          :interval="0.1"
          :min="0.1"
          :max="200"
        />
      </div>
    </div>
    <div>
      <Fieldset title="Outline">
        <div>
          <label>Enable</label>
          <Toggle v-model="newSettings.outline.enabled" />
        </div>
        <div v-show="newSettings.outline.enabled">
          <div>
            <label for="color">Color</label>
            <ColorPicker
              :tooltip="'none'"
              v-model="newSettings.outline.color"
              @input="$emit('updateLayer', this.newSettings)"
            />
          </div>
          <div>
            <label>Width: {{ newSettings.outline.width }}</label>
            <vue-slider
              :tooltip="'none'"
              v-model="newSettings.outline.width"
              @change="$emit('updateLayer', this.newSettings)"
              :interval="1"
              :min="1"
              :max="100"
            />
          </div>
        </div>
      </Fieldset>
    </div>
    <div>
      <Fieldset title="Fill">
        <div>
          <label>Enable</label>
          <Toggle v-model="newSettings.fill.enabled" />
        </div>
        <div v-show="newSettings.fill.enabled">
          <div>
            <label for="color">Color</label>
            <ColorPicker
              v-model="newSettings.fill.color"
              @input="$emit('updateLayer', this.newSettings)"
            />
          </div>
        </div>
      </Fieldset>
    </div>
    <div>
      <Fieldset title="Offsets">
        <div>
          <label>Top: {{ newSettings.offset.top }}</label>
          <vue-slider
            :tooltip="'none'"
            v-model="newSettings.offset.top"
            @change="$emit('updateLayer', this.newSettings)"
            :min="-150"
            :max="150"
          />
        </div>
        <div>
          <label>Right: {{ newSettings.offset.right }}</label>
          <vue-slider
            :tooltip="'none'"
            v-model="newSettings.offset.right"
            @change="$emit('updateLayer', this.newSettings)"
            :min="-150"
            :max="150"
          />
        </div>
      </Fieldset>
    </div>
  </div>
</template>

<script>
import VueSlider from "vue-slider-component";
import Fieldset from "../../../Fieldset.vue";
import Toggle from "@vueform/toggle";
import ColorPicker from "../../../ColorPicker.vue";
import { useCrosshairStore } from "../../../../stores/crosshair";

export default {
  components: { VueSlider, Toggle, Fieldset, ColorPicker },
  name: "circle-config",
  emits: ["updateLayer", "updateLayerKey"],
  setup() {
    const crosshair = useCrosshairStore();
    console.log(crosshair.getLayerByIndex(0).width);
    return {
      updateLayerKey2: crosshair.updateLayerKey,
      selectedLayer: crosshair.getLayerByIndex(0),
    };
  },
  methods: {
    updateSettings(newVal) {
      console.log(newVal);
    },
    testara() {
      //console.log(this.newSettings.width);
    },
  },
  data() {
    return {
      newSettings: {},
    };
  },
  created() {
    this.newSettings = { ...this.setting };
    this.$watch("newSettings", this.updateSettings, { deep: true });
  },
  props: {
    setting: {
      type: Object,
    },
  },
};
</script>

<style lang="scss" scoped>
div {
  display: flex;
  flex-direction: column;
  margin: 5px 0;
}

label {
  font-weight: 400;
}
</style>
